-- Server-authoritative XP, verified learning sessions, and atomic shop purchases.
-- Safe to run after 202611070001_user_progress.sql. Existing payload rows are preserved;
-- their XP/inventory are copied once into account_state before client write access is removed.

create table if not exists public.account_state (
  user_id uuid primary key references auth.users(id) on delete cascade,
  xp_balance bigint not null default 0 check (xp_balance >= 0),
  total_xp_earned bigint not null default 0 check (total_xp_earned >= 0),
  inventory jsonb not null default '{"hearts":5,"streakFreezes":0,"shieldActive":false,"activeBoosterUntil":0,"unlockedTitles":["Novize (Новичок)"],"activeTitle":"Novize (Новичок)","purchasedItems":[],"equippedItems":{"avatar":"👨‍🚀","frame":"","theme":""}}'::jsonb,
  local_imported_at timestamptz,
  updated_at timestamptz not null default now()
);

create table if not exists public.xp_transactions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  amount bigint not null check (amount <> 0),
  kind text not null check (kind in ('opening_balance','verified_session','shop_purchase')),
  reference_key text not null,
  item_id text,
  created_at timestamptz not null default now(),
  unique(user_id, reference_key)
);

create table if not exists public.shop_catalog (
  item_id text primary key,
  price integer not null check (price >= 0),
  consumable boolean not null default false,
  effect text not null,
  effect_value text,
  equipped_key text,
  enabled boolean not null default true
);

create table if not exists public.user_purchases (
  user_id uuid not null references auth.users(id) on delete cascade,
  item_id text not null references public.shop_catalog(item_id),
  quantity integer not null default 1 check (quantity > 0),
  first_purchased_at timestamptz not null default now(),
  primary key(user_id,item_id)
);

insert into public.shop_catalog(item_id,price,consumable,effect,effect_value,equipped_key) values
 ('shield',150,true,'shield','true',null),('freeze',250,true,'freeze','1',null),
 ('booster',200,true,'booster','15',null),('hearts_refill',100,true,'hearts','5',null),
 ('title_Der Zaren-Lerner (Царь)',300,false,'title','Der Zaren-Lerner (Царь)','activeTitle'),
 ('title_Straßen-Boss (Чувак)',400,false,'title','Straßen-Boss (Чувак)','activeTitle'),
 ('title_Kosmonaut (Космонавт)',600,false,'title','Kosmonaut (Космонавт)','activeTitle'),
 ('avatar_cat',150,false,'cosmetic','🐈','avatar'),('avatar_mage',250,false,'cosmetic','🧙','avatar'),('avatar_cosmonaut',350,false,'cosmetic','👩‍🚀','avatar'),
 ('frame_gold',300,false,'cosmetic','gold','frame'),('frame_aurora',500,false,'cosmetic','aurora','frame'),
 ('theme_ocean',350,false,'cosmetic','ocean','theme'),('theme_sunset',450,false,'cosmetic','sunset','theme'),('theme_forest',450,false,'cosmetic','forest','theme')
on conflict(item_id) do update set price=excluded.price, consumable=excluded.consumable, effect=excluded.effect, effect_value=excluded.effect_value, equipped_key=excluded.equipped_key, enabled=true;

-- Preserve values from existing accounts, once only. Client-submitted values are ignored thereafter.
insert into public.account_state(user_id,xp_balance,total_xp_earned,inventory)
select p.user_id,
       greatest(0,case when (p.payload->>'xp') ~ '^[0-9]+$' and length(p.payload->>'xp')<=18 then (p.payload->>'xp')::bigint else 0 end),
       greatest(0,case when (p.payload#>>'{stats,totalXpEarned}') ~ '^[0-9]+$' and length(p.payload#>>'{stats,totalXpEarned}')<=18 then (p.payload#>>'{stats,totalXpEarned}')::bigint else 0 end),
       (case when jsonb_typeof(p.payload->'inventory')='object' then p.payload->'inventory' else '{}'::jsonb end) || jsonb_build_object('hearts',greatest(0,least(5,case when (p.payload->>'hearts') ~ '^[0-9]+$' and length(p.payload->>'hearts')<=9 then (p.payload->>'hearts')::integer else 5 end)))
from public.user_progress p
on conflict(user_id) do nothing;

insert into public.xp_transactions(user_id,amount,kind,reference_key)
select user_id,xp_balance,'opening_balance','migration_v2_opening_balance'
from public.account_state where xp_balance > 0
on conflict(user_id,reference_key) do nothing;

insert into public.user_purchases(user_id,item_id,quantity)
select s.user_id, item.item_id, 1
from public.account_state s
cross join lateral jsonb_array_elements_text(case when jsonb_typeof(s.inventory->'purchasedItems')='array' then s.inventory->'purchasedItems' else '[]'::jsonb end) owned(item_id)
join public.shop_catalog item on item.item_id=owned.item_id and not item.consumable
on conflict(user_id,item_id) do nothing;

insert into public.user_purchases(user_id,item_id,quantity)
select s.user_id,item.item_id,1
from public.account_state s
join public.shop_catalog item on item.effect='title' and coalesce(s.inventory->'unlockedTitles','[]'::jsonb) @> jsonb_build_array(item.effect_value)
on conflict(user_id,item_id) do nothing;

create table if not exists public.learning_questions (
  question_id text primary key,
  lesson_id text,
  answer_kind text not null check (answer_kind in ('choice','text','matching')),
  expected jsonb not null
);

create table if not exists public.learning_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  mode text not null check (mode in ('lesson','practice','heart_refill')),
  lesson_id text,
  question_ids text[] not null check (cardinality(question_ids) between 1 and 60),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '2 hours',
  completed_at timestamptz,
  xp_awarded integer not null default 0 check (xp_awarded >= 0),
  correct_count integer not null default 0 check (correct_count >= 0),
  mistake_count integer not null default 0 check (mistake_count >= 0)
);
alter table public.learning_sessions add column if not exists mistake_count integer not null default 0 check (mistake_count >= 0);

create table if not exists public.learning_session_answers (
  session_id uuid not null references public.learning_sessions(id) on delete cascade,
  question_id text not null references public.learning_questions(question_id),
  user_id uuid not null references auth.users(id) on delete cascade,
  answer jsonb not null,
  is_correct boolean not null,
  submitted_at timestamptz not null default now(),
  primary key(session_id,question_id)
);
create table if not exists public.learning_session_mistakes (
  session_id uuid not null references public.learning_sessions(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  attempt_id uuid not null,
  created_at timestamptz not null default now(),
  primary key(session_id,attempt_id)
);

create table if not exists public.lesson_rewards (
  user_id uuid not null references auth.users(id) on delete cascade,
  lesson_id text not null,
  awarded_at timestamptz not null default now(),
  primary key(user_id,lesson_id)
);

alter table public.account_state enable row level security;
alter table public.xp_transactions enable row level security;
alter table public.user_purchases enable row level security;
alter table public.shop_catalog enable row level security;
alter table public.learning_questions enable row level security;
alter table public.learning_sessions enable row level security;
alter table public.learning_session_answers enable row level security;
alter table public.learning_session_mistakes enable row level security;
alter table public.lesson_rewards enable row level security;

drop policy if exists "read own learning progress" on public.user_progress;
drop policy if exists "insert own learning progress" on public.user_progress;
drop policy if exists "update own learning progress" on public.user_progress;
drop policy if exists "read own account state" on public.account_state;
drop policy if exists "read own xp history" on public.xp_transactions;
drop policy if exists "read own purchases" on public.user_purchases;
drop policy if exists "read own sessions" on public.learning_sessions;
drop policy if exists "read own answers" on public.learning_session_answers;
drop policy if exists "read own mistakes" on public.learning_session_mistakes;
drop policy if exists "read own lesson rewards" on public.lesson_rewards;
create policy "read own learning progress" on public.user_progress for select to authenticated using (auth.uid() = user_id);
create policy "read own account state" on public.account_state for select to authenticated using (auth.uid() = user_id);
create policy "read own xp history" on public.xp_transactions for select to authenticated using (auth.uid() = user_id);
create policy "read own purchases" on public.user_purchases for select to authenticated using (auth.uid() = user_id);
create policy "read own sessions" on public.learning_sessions for select to authenticated using (auth.uid() = user_id);
create policy "read own answers" on public.learning_session_answers for select to authenticated using (auth.uid() = user_id);
create policy "read own mistakes" on public.learning_session_mistakes for select to authenticated using (auth.uid() = user_id);
create policy "read own lesson rewards" on public.lesson_rewards for select to authenticated using (auth.uid() = user_id);

revoke all on public.account_state, public.xp_transactions, public.user_purchases, public.shop_catalog, public.learning_questions, public.learning_sessions, public.learning_session_answers, public.learning_session_mistakes, public.lesson_rewards from anon, authenticated;
grant select on public.account_state, public.xp_transactions, public.user_purchases, public.learning_sessions, public.learning_session_answers, public.learning_session_mistakes, public.lesson_rewards to authenticated;
revoke insert, update, delete on public.user_progress from anon, authenticated;
grant select on public.user_progress to authenticated;

create or replace function public.merge_progress_json(old_value jsonb,new_value jsonb)
returns jsonb language plpgsql immutable set search_path = pg_catalog, public as $$
declare result jsonb := coalesce(old_value,'{}'::jsonb); k text; v jsonb;
begin
  if jsonb_typeof(new_value)='object' and jsonb_typeof(result)='object' then
    for k,v in select key,value from jsonb_each(new_value) loop
      if result ? k then result := jsonb_set(result,array[k],public.merge_progress_json(result->k,v),true);
      else result := jsonb_set(result,array[k],v,true); end if;
    end loop;
    return result;
  elsif jsonb_typeof(new_value)='array' and jsonb_typeof(result)='array' then
    return (select coalesce(jsonb_agg(item),'[]'::jsonb) from (select distinct item from jsonb_array_elements(result || new_value) as e(item)) merged);
  end if;
  return coalesce(new_value,result);
end; $$;
revoke all on function public.merge_progress_json(jsonb,jsonb) from public,anon,authenticated;

create or replace function public.merge_import_progress(existing_value jsonb,local_value jsonb)
returns jsonb language plpgsql immutable set search_path = pg_catalog,public as $$
declare result jsonb:=coalesce(existing_value,'{}'::jsonb); k text; v jsonb;
begin
  if jsonb_typeof(local_value)='object' and jsonb_typeof(result)='object' then
    for k,v in select key,value from jsonb_each(local_value) loop
      if result ? k then result:=jsonb_set(result,array[k],public.merge_import_progress(result->k,v),true);
      else result:=jsonb_set(result,array[k],v,true); end if;
    end loop;
    return result;
  elsif jsonb_typeof(local_value)='array' and jsonb_typeof(result)='array' then
    return (select coalesce(jsonb_agg(item),'[]'::jsonb) from (select distinct item from jsonb_array_elements(result||local_value) as e(item)) merged);
  end if;
  return coalesce(result,local_value);
end; $$;
revoke all on function public.merge_import_progress(jsonb,jsonb) from public,anon,authenticated;

create or replace function public.sync_user_progress(new_payload jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog, public as $$
declare uid uuid := auth.uid(); state public.account_state%rowtype; clean_payload jsonb; merged_payload jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if new_payload is null or pg_column_size(new_payload)>524288 then raise exception 'Invalid progress payload'; end if;
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  clean_payload := jsonb_set(new_payload - 'xp' - 'inventory' - 'hearts','{stats}',coalesce(new_payload->'stats','{}'::jsonb)-'totalXpEarned',true);
  insert into public.user_progress(user_id,payload) values(uid,clean_payload)
  on conflict(user_id) do update set payload=public.merge_progress_json(jsonb_set(public.user_progress.payload - 'xp' - 'inventory' - 'hearts','{stats}',coalesce(public.user_progress.payload->'stats','{}'::jsonb)-'totalXpEarned',true),excluded.payload), updated_at=now()
  returning payload into merged_payload;
  merged_payload := merged_payload || jsonb_build_object('xp',state.xp_balance,'inventory',state.inventory,'hearts',coalesce((state.inventory->>'hearts')::integer,5));
  merged_payload := jsonb_set(merged_payload,'{stats,totalXpEarned}',to_jsonb(state.total_xp_earned),true);
  return merged_payload;
end; $$;
revoke all on function public.sync_user_progress(jsonb) from public,anon,authenticated;
grant execute on function public.sync_user_progress(jsonb) to authenticated;

create or replace function public.normalize_answer(value text)
returns text language sql immutable set search_path = pg_catalog as $$
  select trim(regexp_replace(lower(replace(coalesce(value,''),'ё','е')),'[[:space:][:punct:]]+',' ','g'));
$$;
revoke all on function public.normalize_answer(text) from public,anon,authenticated;

create or replace function public.canonical_pairs(value jsonb)
returns jsonb language sql immutable set search_path = pg_catalog,public as $$
  select coalesce(jsonb_agg(jsonb_build_object('left',public.normalize_answer(pair->>'left'),'right',public.normalize_answer(pair->>'right')) order by public.normalize_answer(pair->>'left'),public.normalize_answer(pair->>'right')),'[]'::jsonb)
  from jsonb_array_elements(coalesce(value,'[]'::jsonb)) as p(pair);
$$;
revoke all on function public.canonical_pairs(jsonb) from public,anon,authenticated;

create or replace function public.begin_learning_session(p_question_ids text[],p_mode text,p_lesson_id text default null)
returns uuid language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid := auth.uid(); session_id uuid; found_count integer;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if p_mode not in ('lesson','practice','heart_refill') or cardinality(p_question_ids) not between 1 and 60 or cardinality(p_question_ids)<>(select count(distinct qid) from unnest(p_question_ids) q(qid)) then raise exception 'Invalid session request'; end if;
  if p_mode='lesson' and (p_lesson_id is null or not exists(select 1 from public.learning_questions where lesson_id=p_lesson_id)) then raise exception 'Unknown lesson'; end if;
  if p_mode='lesson' and cardinality(p_question_ids)<>(select count(*) from public.learning_questions where lesson_id=p_lesson_id) then raise exception 'A lesson session must include every question'; end if;
  select count(*) into found_count from public.learning_questions q where q.question_id=any(p_question_ids) and (p_mode<>'lesson' or q.lesson_id=p_lesson_id);
  if found_count<>cardinality(p_question_ids) then raise exception 'Session contains unknown or mismatched questions'; end if;
  if (select count(*) from public.learning_sessions where user_id=uid and created_at>now()-interval '1 hour')>=40 then raise exception 'Too many learning sessions'; end if;
  insert into public.learning_sessions(user_id,mode,lesson_id,question_ids) values(uid,p_mode,p_lesson_id,p_question_ids) returning id into session_id;
  return session_id;
end; $$;
revoke all on function public.begin_learning_session(text[],text,text) from public,anon,authenticated;
grant execute on function public.begin_learning_session(text[],text,text) to authenticated;

create or replace function public.submit_learning_answer(p_session_id uuid,p_question_id text,p_answer jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid := auth.uid(); sess public.learning_sessions%rowtype; q public.learning_questions%rowtype; ok boolean; prior public.learning_session_answers%rowtype; state public.account_state%rowtype; inv jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into sess from public.learning_sessions where id=p_session_id and user_id=uid for update;
  if not found or sess.completed_at is not null or sess.expires_at<now() or not (p_question_id=any(sess.question_ids)) then raise exception 'Invalid or expired session'; end if;
  select * into prior from public.learning_session_answers where session_id=sess.id and question_id=p_question_id;
  if found then return jsonb_build_object('correct',prior.is_correct,'recorded',false); end if;
  select * into q from public.learning_questions where question_id=p_question_id;
  if q.answer_kind='matching' then
    ok := public.canonical_pairs(p_answer->'pairs')=public.canonical_pairs(q.expected->'pairs');
  else
    ok := public.normalize_answer(p_answer->>'value')=public.normalize_answer(q.expected->>'value');
  end if;
  insert into public.learning_session_answers(session_id,question_id,user_id,answer,is_correct) values(sess.id,p_question_id,uid,coalesce(p_answer,'{}'::jsonb),ok);
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  if not ok then
    inv:=state.inventory;
    if coalesce((inv->>'shieldActive')::boolean,false) then inv:=jsonb_set(inv,'{shieldActive}','false'::jsonb,true);
    else inv:=jsonb_set(inv,'{hearts}',to_jsonb(greatest(0,coalesce((inv->>'hearts')::integer,5)-1)),true); end if;
    update public.account_state set inventory=inv,updated_at=now() where user_id=uid returning * into state;
  end if;
  return jsonb_build_object('correct',ok,'recorded',true,'inventory',state.inventory,'hearts',coalesce((state.inventory->>'hearts')::integer,5));
end; $$;
revoke all on function public.submit_learning_answer(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.submit_learning_answer(uuid,text,jsonb) to authenticated;

create or replace function public.record_learning_mistake(p_session_id uuid,p_attempt_id uuid)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid:=auth.uid(); sess public.learning_sessions%rowtype; state public.account_state%rowtype; inv jsonb; inserted integer;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if p_attempt_id is null then raise exception 'Attempt identifier required'; end if;
  select * into sess from public.learning_sessions where id=p_session_id and user_id=uid and completed_at is null and expires_at>now() for update;
  if not found then raise exception 'Invalid or expired session'; end if;
  insert into public.learning_session_mistakes(session_id,user_id,attempt_id) values(sess.id,uid,p_attempt_id) on conflict do nothing;
  get diagnostics inserted = row_count;
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  if inserted>0 then
    inv:=state.inventory;
    if coalesce((inv->>'shieldActive')::boolean,false) then inv:=jsonb_set(inv,'{shieldActive}','false'::jsonb,true);
    else inv:=jsonb_set(inv,'{hearts}',to_jsonb(greatest(0,coalesce((inv->>'hearts')::integer,5)-1)),true); end if;
    update public.account_state set inventory=inv,updated_at=now() where user_id=uid returning * into state;
    update public.learning_sessions set mistake_count=mistake_count+1 where id=sess.id returning * into sess;
  end if;
  return jsonb_build_object('inventory',state.inventory,'hearts',coalesce((state.inventory->>'hearts')::integer,5),'recorded',inserted>0);
end; $$;
revoke all on function public.record_learning_mistake(uuid,uuid) from public,anon,authenticated;
grant execute on function public.record_learning_mistake(uuid,uuid) to authenticated;

create or replace function public.finish_learning_session(p_session_id uuid)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid := auth.uid(); sess public.learning_sessions%rowtype; answered integer; correct integer; base_reward integer; lesson_bonus integer:=0; daily_earned bigint; awarded integer; state public.account_state%rowtype; perfect boolean; boosted boolean:=false;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into sess from public.learning_sessions where id=p_session_id and user_id=uid for update;
  if not found or sess.expires_at<now() then raise exception 'Invalid or expired session'; end if;
  if sess.completed_at is not null then
    select * into state from public.account_state where user_id=uid;
    return jsonb_build_object('xp_awarded',sess.xp_awarded,'xp_balance',state.xp_balance,'inventory',state.inventory,'correct_count',sess.correct_count,'duplicate',true);
  end if;
  select count(*),count(*) filter(where is_correct) into answered,correct from public.learning_session_answers where session_id=sess.id and user_id=uid;
  if answered<>cardinality(sess.question_ids) then raise exception 'All questions must be submitted before finishing'; end if;
  perfect := correct=answered and sess.mistake_count=0;
  base_reward := correct*5+10+case when perfect then 10 else 0 end;
  if sess.mode='heart_refill' then base_reward:=20; end if;
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  boosted:=coalesce((state.inventory->>'activeBoosterUntil')::bigint,0)>floor(extract(epoch from now())*1000);
  if boosted then base_reward:=base_reward*2; end if;
  if sess.mode='lesson' then
    insert into public.lesson_rewards(user_id,lesson_id) values(uid,sess.lesson_id) on conflict do nothing;
    if found then lesson_bonus:=15; end if;
  end if;
  select coalesce(sum(amount),0) into daily_earned from public.xp_transactions where user_id=uid and amount>0 and created_at>=date_trunc('day',now());
  awarded := least(base_reward+lesson_bonus,greatest(0,300-daily_earned));
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  update public.account_state set xp_balance=xp_balance+awarded,total_xp_earned=total_xp_earned+awarded,inventory=case when sess.mode='heart_refill' then jsonb_set(inventory,'{hearts}','5'::jsonb,true) else inventory end,updated_at=now() where user_id=uid returning * into state;
  if awarded>0 then insert into public.xp_transactions(user_id,amount,kind,reference_key) values(uid,awarded,'verified_session','session:'||sess.id::text); end if;
  update public.learning_sessions set completed_at=now(),xp_awarded=awarded,correct_count=correct where id=sess.id;
  return jsonb_build_object('xp_awarded',awarded,'xp_balance',state.xp_balance,'total_xp_earned',state.total_xp_earned,'inventory',state.inventory,'correct_count',correct,'perfect',perfect,'is_boosted',boosted,'daily_cap_reached',daily_earned+awarded>=300);
end; $$;
revoke all on function public.finish_learning_session(uuid) from public,anon,authenticated;
grant execute on function public.finish_learning_session(uuid) to authenticated;

create or replace function public.purchase_shop_item(p_item_id text,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid:=auth.uid(); item public.shop_catalog%rowtype; state public.account_state%rowtype; old_tx public.xp_transactions%rowtype; inv jsonb; new_qty integer;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if p_request_id is null then raise exception 'Request identifier required'; end if;
  select * into old_tx from public.xp_transactions where user_id=uid and reference_key='purchase:'||p_request_id::text;
  if found then
    if old_tx.item_id<>p_item_id then raise exception 'Request identifier already used'; end if;
    select * into state from public.account_state where user_id=uid;
    return jsonb_build_object('success',true,'duplicate',true,'xp_balance',state.xp_balance,'inventory',state.inventory);
  end if;
  select * into item from public.shop_catalog where item_id=p_item_id and enabled;
  if not found then raise exception 'Unknown shop item'; end if;
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  -- Serialize duplicate requests and make retries with the same request UUID idempotent.
  select * into old_tx from public.xp_transactions where user_id=uid and reference_key='purchase:'||p_request_id::text;
  if found then
    if old_tx.item_id<>p_item_id then raise exception 'Request identifier already used'; end if;
    return jsonb_build_object('success',true,'duplicate',true,'xp_balance',state.xp_balance,'inventory',state.inventory);
  end if;
  if not item.consumable and exists(select 1 from public.user_purchases where user_id=uid and item_id=item.item_id) then raise exception 'Item already owned'; end if;
  if state.xp_balance<item.price then raise exception 'Insufficient XP'; end if;
  update public.account_state set xp_balance=xp_balance-item.price,inventory=inventory||jsonb_build_object('purchasedItems',case when item.consumable then coalesce(inventory->'purchasedItems','[]'::jsonb) else coalesce(inventory->'purchasedItems','[]'::jsonb)||jsonb_build_array(item.item_id) end),updated_at=now() where user_id=uid returning * into state;
  insert into public.xp_transactions(user_id,amount,kind,reference_key,item_id) values(uid,-item.price,'shop_purchase','purchase:'||p_request_id::text,item.item_id);
  insert into public.user_purchases(user_id,item_id,quantity) values(uid,item.item_id,1) on conflict(user_id,item_id) do update set quantity=public.user_purchases.quantity+1;
  inv:=state.inventory;
  if item.effect='shield' then inv:=jsonb_set(inv,'{shieldActive}','true'::jsonb,true);
  elsif item.effect='freeze' then inv:=jsonb_set(inv,'{streakFreezes}',to_jsonb(coalesce((inv->>'streakFreezes')::integer,0)+1),true);
  elsif item.effect='booster' then inv:=jsonb_set(inv,'{activeBoosterUntil}',to_jsonb(floor(extract(epoch from now()+make_interval(mins=>item.effect_value::integer))*1000)::bigint),true);
  elsif item.effect='hearts' then inv:=jsonb_set(inv,'{hearts}',to_jsonb(item.effect_value::integer),true);
  elsif item.effect='title' then
    if not coalesce(inv->'unlockedTitles','[]'::jsonb) @> jsonb_build_array(item.effect_value) then inv:=jsonb_set(inv,'{unlockedTitles}',coalesce(inv->'unlockedTitles','[]'::jsonb)||jsonb_build_array(item.effect_value),true); end if;
    inv:=jsonb_set(inv,'{activeTitle}',to_jsonb(item.effect_value),true);
  elsif item.effect='cosmetic' then inv:=jsonb_set(inv,array['equippedItems',item.equipped_key],to_jsonb(item.effect_value),true);
  end if;
  update public.account_state set inventory=inv,updated_at=now() where user_id=uid returning * into state;
  return jsonb_build_object('success',true,'duplicate',false,'xp_balance',state.xp_balance,'inventory',state.inventory,'item_id',item.item_id);
end; $$;
revoke all on function public.purchase_shop_item(text,uuid) from public,anon,authenticated;
grant execute on function public.purchase_shop_item(text,uuid) to authenticated;

create or replace function public.equip_shop_item(p_item_id text)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid:=auth.uid(); item public.shop_catalog%rowtype; state public.account_state%rowtype; inv jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into item from public.shop_catalog where item_id=p_item_id and enabled and equipped_key is not null;
  if not found then raise exception 'Item cannot be equipped'; end if;
  if not exists(select 1 from public.user_purchases where user_id=uid and item_id=p_item_id) then raise exception 'Item not owned'; end if;
  select * into state from public.account_state where user_id=uid for update;
  if item.equipped_key='activeTitle' then inv:=jsonb_set(state.inventory,'{activeTitle}',to_jsonb(item.effect_value),true);
  else inv:=jsonb_set(state.inventory,array['equippedItems',item.equipped_key],to_jsonb(item.effect_value),true); end if;
  update public.account_state set inventory=inv,updated_at=now() where user_id=uid returning * into state;
  return jsonb_build_object('inventory',state.inventory,'xp_balance',state.xp_balance);
end; $$;
revoke all on function public.equip_shop_item(text) from public,anon,authenticated;
grant execute on function public.equip_shop_item(text) to authenticated;

create or replace function public.import_local_progress(local_payload jsonb)
returns jsonb language plpgsql security definer set search_path = pg_catalog,public as $$
declare uid uuid:=auth.uid(); state public.account_state%rowtype; clean jsonb; merged jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  if local_payload is null or pg_column_size(local_payload)>524288 then raise exception 'Invalid local data'; end if;
  insert into public.account_state(user_id) values(uid) on conflict(user_id) do nothing;
  select * into state from public.account_state where user_id=uid for update;
  if state.local_imported_at is not null then raise exception 'Local import already used for this account'; end if;
  clean:=jsonb_set(local_payload-'xp'-'inventory'-'hearts','{stats}',coalesce(local_payload->'stats','{}'::jsonb)-'totalXpEarned',true);
  insert into public.user_progress(user_id,payload) values(uid,clean)
  on conflict(user_id) do update set payload=public.merge_import_progress(public.user_progress.payload,excluded.payload),updated_at=now() returning payload into merged;
  update public.account_state set local_imported_at=now() where user_id=uid returning * into state;
  merged:=merged||jsonb_build_object('xp',state.xp_balance,'inventory',state.inventory,'hearts',coalesce((state.inventory->>'hearts')::integer,5));
  merged:=jsonb_set(merged,'{stats,totalXpEarned}',to_jsonb(state.total_xp_earned),true);
  return merged;
end; $$;
revoke all on function public.import_local_progress(jsonb) from public,anon,authenticated;
grant execute on function public.import_local_progress(jsonb) to authenticated;

